import telnetlib
from robot.api import logger


class GetLMTSCommandOutput(object):
    def __init__(self, host='10.42.104.133'):
        self.host = host

    def get_lmts_command_output(self, test_line, command, dsp):
        """
        :param test_line: IOT_TLx - telnet port depends on which TL for NB-IoT is chosen
        :param command: command executed on one of LMTS DSPs
        :param dsp: LMTS DSP (DSPA, DSPB, DSPC)
        :return: output of command executed on one of LMTS DSPs
        """
        self.command = command
        self.test_line = test_line
        self.dsp = dsp.upper()
        self.port = self._get_port_number_for_specific_lmts()
        return self._get_raw_lmts_output(self.command)

    def _get_port_number_for_specific_lmts(self):
        """
        :return: returns port number for telnet connection
        """
        port_number_for_lmts = {
            'Wroclaw.IOT_TL1': {'DSPA': 15011, 'DSPB': 15012, 'DSPC': 15013},
            'Wroclaw.IOT_TL2': {'DSPA': 15031, 'DSPB': 15032, 'DSPC': 15033},
            'Wroclaw.IOT_TL3': {'DSPA': 15051, 'DSPB': 15052, 'DSPC': 15053},
        }
        return port_number_for_lmts[self.test_line][self.dsp]

    def _get_raw_lmts_output(self, command):
        """
        :return: returns result of command executed on LMTS
        """
        logger.console((self.port))
        try:
            tn = telnetlib.Telnet(self.host, self.port, 10)
        except IOError:
            logger.console('socket timeout')
        else:
            tn.read_until('CLIENT1 [] has just connected!', 5)
            tn.write(command + '\n')
            raw_lmts_output = tn.read_until('BCU3.' + self.dsp + '.core0>', 5)
            if raw_lmts_output:
                tn.write('\x1D\n')
                tn.read_until('telnet>', 5)
                tn.write('\x04')
                tn.close()
                return raw_lmts_output
            else:
                logger.console('ERROR: Most probably telnet connection is already open... \n')
